<script setup lang="ts">
import { computed, reactive, watch } from 'vue'
import type { Cell } from '../api/client'
import { COMMAND_LABELS, GOAL_LABELS, KIND_LABELS, POSTURE_LABELS, REASON_LABELS, STATUS_LABELS, TASK_LABELS, WAKE_LABELS, actionLabel, directionLabel, formatCell, goalLabel, reasonLabel, statusLabel, taskLabel, wakeLabel } from '../domain/labels'
import { useDashboardStore } from '../state/dashboard'

const dashboard = useDashboardStore()
const form = reactive({ password: '', taskAlias: '', taskKind: 'HOLD_POSITION', taskPriority: '800', taskTarget: '', migrationTarget: '' })
const overrides = reactive<Record<string, string>>({})
const configLabels: Record<string, string> = {
  core_guard_vanguards: '核心守卫·先锋人数', core_guard_rangers: '核心守卫·游侠人数', intercept_vanguards: '远征编组·先锋编制',
  intercept_rangers: '远征编组·游侠编制', resource_recheck_worker_limit: '矿区护航·工兵编制', early_workers: '初期工人',
  early_vanguards: '初期先锋', early_rangers: '初期游侠', patrol_radius_min: '巡逻半径·最小', patrol_radius_max: '巡逻半径·最大',
  patrol_arc_segments: '巡逻弧段数', patrol_radius_units_per_step: '巡逻半径扩张单位数', minimum_resource_reserve: '最低资源储备', peacetime_resource_buffer: '和平期资源缓冲',
}
watch(() => dashboard.selectedAlias.value, alias => { if (alias) form.taskAlias = alias }, { immediate: true })
watch(() => dashboard.policyOverrides.value, next => Object.keys(configLabels).forEach(key => { overrides[key] = next[key] == null ? '' : String(next[key]) }), { immediate: true, deep: true })
watch(() => dashboard.mapTarget.value, cell => { if (cell) { form.taskTarget = cell.join(','); form.taskKind = 'MOVE_TO_CELL' } })

const view = computed(() => dashboard.displayView.value)
const current = computed(() => view.value?.current)
const commandCenter = computed(() => view.value?.command_center || {})
const entities = computed(() => dashboard.entities.value)
const selected = computed(() => dashboard.selectedEntity.value)
const nearbyResources = computed(() => {
  const resources = current.value?.map?.resources || []
  const origin = selected.value?.position || current.value?.map?.friendly?.find(item => item.kind === 'CORE')?.position || [0, 0]
  return resources.map(position => ({ position, distance: Math.abs(position[0] - origin[0]) + Math.abs(position[1] - origin[1]) })).sort((a, b) => a.distance - b.distance || a.position[0] - b.position[0] || a.position[1] - b.position[1]).slice(0, 8)
})
const policyConfig = computed(() => view.value?.policy_config || {})
const migration = computed(() => view.value?.migration_recommendation || {})
const chunks = computed(() => view.value?.chunk_saturation || {})
const taskAliasOptions = computed(() => entities.value.filter(entity => /^entity_[0-9a-f]{12}$/.test(entity.alias)))
const migrationFresh = computed(() => {
  const tick = Number(current.value?.tick || 0)
  const rec = migration.value
  return Boolean(rec.center) && tick - Number(rec.computed_at_tick || 0) < Number(rec.interval_ticks || 60) * 2
})

async function login() { await dashboard.login(form.password) }
async function assign() { await dashboard.assignTask(form.taskAlias, form.taskKind, Number(form.taskPriority), parseTarget(form.taskTarget)) }
async function migrate() {
  const target = parseTarget(form.migrationTarget)
  if (!target) { dashboard.taskState.value = '迁移目标必须是 x,y。'; return }
  if (window.confirm('确认排队 Core 迁移？执行时仍会重新校验安全性。')) await dashboard.migrate(target)
}
function parseTarget(value: string): Cell | null {
  const match = value.trim().match(/^(-?\d+)\s*,\s*(-?\d+)$/)
  return match ? [Number(match[1]), Number(match[2])] : null
}
function policySubmit() {
  const values: Record<string, number> = {}
  Object.entries(overrides).forEach(([key, value]) => { if (value.trim() !== '' && Number.isInteger(Number(value))) values[key] = Number(value) })
  void dashboard.setPolicy(dashboard.policyPosture.value, values)
}
function selectEntity(alias: string) { dashboard.selectUnit(alias) }
function focusResource(position: Cell) { dashboard.focusCell(position) }
function commandLabel(type: unknown) { return COMMAND_LABELS[String(type)] || String(type || '其他') }
</script>

<template>
  <aside class="panel situation-panel">
    <section class="situation-section"><div class="section-head"><div><span class="eyebrow">SELECTED ELEMENT</span><h2>单位状态与决策链</h2></div></div><div id="unitDetail" class="unit-detail">
      <div v-if="!selected" class="empty-detail">从左侧选择单位</div>
      <article v-else class="unit-card" :class="{ 'is-running': selected.status === 'RUNNING', 'is-blocked': selected.blocker }"><header class="unit-head"><div><b>{{ KIND_LABELS[selected.kind || ''] || selected.kind || '单位' }}</b><span class="alias">{{ selected.alias }}</span></div><span class="state-pill">{{ statusLabel(selected.status || 'UNKNOWN') }}</span></header><div class="unit-state"><span v-if="selected.state_synced !== false">位置 {{ formatCell(selected.position) }} · HP {{ selected.hp ?? '—' }}{{ selected.shield == null ? '' : ` · 护盾 ${selected.shield}` }}{{ selected.cargo == null ? '' : ` · 货物 ${selected.cargo}` }}</span><span v-else class="sync-wait">等待下一份权威状态</span><span class="tick">#{{ selected.trace_tick ?? '—' }}</span></div><div class="decision-grid"><div><small>当前任务</small><strong>{{ taskLabel(selected.task) || '空闲' }}</strong><span>{{ goalLabel(selected.goal) || '无目标' }}{{ selected.assignment?.role ? ` · ${KIND_LABELS[selected.assignment.role] || selected.assignment.role}` : '' }}</span></div><div><small>当前动作</small><strong>{{ actionLabel(selected.action) || '—' }}{{ selected.target_cell ? ` → 目标 ${formatCell(selected.target_cell)}` : '' }}</strong><span>{{ reasonLabel(selected.reason) || '无原因' }}</span></div><div class="next-step"><small>下一步</small><strong>{{ actionLabel(selected.next_step) || taskLabel(selected.next_step) || '等待新决策' }}</strong><span>{{ wakeLabel(selected.wake_condition) || reasonLabel(selected.blocker) || '无触发条件' }}{{ selected.eta_ticks == null ? '' : ` · 预计 ${selected.eta_ticks} Tick` }}</span></div></div><div class="unit-meta">{{ selected.assignment?.lock ? `目标锁 ${selected.assignment.lock} · ` : '' }}{{ selected.assignment?.lease_until_tick == null ? '' : `租约至 #${selected.assignment.lease_until_tick} · ` }}{{ selected.waited_ticks ? `已等待 ${selected.waited_ticks} Tick` : '' }}</div><div v-if="selected.action === 'WAIT'" class="unit-meta">停滞诊断：{{ selected.wait_kind || 'UNKNOWN_WAIT' }} · {{ reasonLabel(selected.blocker || selected.reason) || '等待下一份权威状态' }}</div><details><summary>查看决策链</summary><div class="trace-columns"><div><b>备选动作</b><ul><li v-for="candidate in selected.candidate_intents || []" :key="`${candidate.action}-${candidate.direction}-${candidate.target_cell}`">{{ actionLabel(candidate.action) }} {{ directionLabel(candidate.direction) }} {{ candidate.target_cell ? `→ ${formatCell(candidate.target_cell)}` : '' }} {{ reasonLabel(candidate.reason) }}</li><li v-if="!selected.candidate_intents?.length">无备选动作</li></ul></div><div><b>行为树路径</b><ul><li v-for="node in selected.node_path || []" :key="node.node_id"><b>{{ node.node_id }}</b> · {{ statusLabel(node.status) }} · {{ reasonLabel(node.reason) }}</li><li v-if="!selected.node_path?.length">无行为树节点</li></ul></div></div></details><button class="neutral select-entity" :data-alias="selected.alias" @click="form.taskAlias = selected.alias">用于任务</button></article>
    </div></section>
    <section class="situation-section"><div class="section-head"><h3>附近资源点</h3><span class="resource-note">余量由协议隐藏</span></div><div id="resourceInfo" class="resource-list muted"><button v-for="item in nearbyResources" :key="item.position.join(',')" class="resource-row" :data-cell="item.position.join(',')" @click="focusResource(item.position)"><span>资源点 {{ item.position.join(',') }} · 距离 {{ item.distance }}</span><small>余量未知</small></button><div v-if="!nearbyResources.length">当前无可见资源点</div></div></section>
    <section class="situation-section"><h3>目标与任务概览</h3><div id="goals" class="compact-list muted"><div v-for="item in commandCenter.goals || []" :key="`${item.goal}-${item.status}`" class="row"><b>{{ goalLabel(item.goal) }}</b> <span class="tag">{{ statusLabel(item.status) }}</span> {{ taskLabel(item.stage) || item.stage }}</div><div v-if="!commandCenter.goals?.length" class="row"><b>当前主线</b> <span class="tag">{{ current?.mode_label || '待命' }}</span> {{ entities.length ? `${entities.length} 个单位` : '暂无单位决策' }}</div></div><div id="tasks" class="compact-list muted"><div v-for="item in commandCenter.tasks || []" :key="item.task_id" class="row"><span v-if="item.tick" class="tick">#{{ item.tick }}</span> <b>{{ item.task_id }}</b> <span class="tag">{{ statusLabel(item.status) }}</span> {{ goalLabel(item.goal) || taskLabel(item.kind) }} {{ item.actor_alias }}{{ item.target ? ` · 目标 ${formatCell(item.target)}` : '' }}{{ item.lease_until_tick == null ? '' : ` · 租约至 #${item.lease_until_tick}` }} {{ reasonLabel(item.reason) }}</div><div v-if="!commandCenter.tasks?.length">当前没有人工或租约任务</div></div></section>
    <details class="order-drawer" open><summary>人工任务 · 地图下令</summary><div class="detail-actions"><p class="muted">只对选中对象生效，下一权威 Tick 会重新校验。</p><div class="auth-row"><input id="password" v-model="form.password" type="password" autocomplete="current-password" placeholder="管理员口令"><button id="login" class="neutral" @click="login">认证</button></div><span id="loginState" class="muted" aria-live="polite">{{ dashboard.loginState }}</span><div class="task-form"><label for="taskAlias">对象</label><select id="taskAlias" v-model="form.taskAlias"><option value="">选择当前实体…</option><option v-for="entity in taskAliasOptions" :key="entity.alias" :value="entity.alias">{{ entity.alias }} · {{ KIND_LABELS[entity.kind || ''] || entity.kind }}</option></select><label for="taskKind">任务</label><select id="taskKind" v-model="form.taskKind"><option value="HOLD_POSITION">原地待命</option><option value="RETREAT_TO_CORE">撤回核心</option><option value="HARVEST_VISIBLE">采集可见资源</option><option value="MOVE_TO_CELL">移动到目标</option></select><label for="taskPriority">优先级</label><select id="taskPriority" v-model="form.taskPriority"><option value="500">普通 · 500</option><option value="800">高 · 800</option><option value="950">紧急 · 950</option></select><label for="taskTarget">目标坐标</label><input id="taskTarget" v-model="form.taskTarget" inputmode="numeric" placeholder="x,y（仅移动）"><button id="assign" class="primary-action" @click="assign">排队任务</button></div><p id="taskState" class="muted" aria-live="polite">{{ dashboard.taskState }}</p><div id="taskCommands" class="command-list muted"><div v-for="item in dashboard.taskCommands.value" :key="item.command_id" class="row"><b>{{ commandLabel(item.type) }}</b> <span class="tag">{{ statusLabel(item.status) }}</span><button v-if="item.status === 'QUEUED'" class="neutral" :data-command="item.command_id" @click="dashboard.cancelCommand(item.command_id)">撤回</button><button v-if="item.status === 'APPLIED' && item.type === 'ASSIGN_TASK'" class="neutral" :data-alias="item.entity_alias" @click="dashboard.cancelEntity(item.entity_alias)">取消任务</button></div><div v-if="!dashboard.taskCommands.value.length">认证后显示人工任务。</div></div></div></details>
    <details class="advanced-drawer"><summary>策略与指挥设置</summary><div class="advanced-grid"><section><h3>核心迁移</h3><input id="migrationTarget" v-model="form.migrationTarget" placeholder="目标 x,y"><div class="button-row"><button id="migrate" class="neutral" @click="migrate">排队迁移</button><button id="cancelMigration" class="neutral" @click="dashboard.cancelMigration">取消</button></div></section><section><h3>策略姿态</h3><p class="muted">生效：<span id="policyCurrent">{{ POSTURE_LABELS[policyConfig.posture] || policyConfig.posture || '均衡' }}</span></p><select id="policyPosture" v-model="dashboard.policyPosture.value"><option value="BALANCED">均衡</option><option value="DEFENSIVE">防御</option><option value="ECONOMY">经济</option><option value="AGGRESSIVE">进攻</option></select><button id="setPolicy" class="neutral" @click="policySubmit">排队策略</button><p id="policyState" class="muted">{{ dashboard.policyState }}</p></section><section><h3>策略参数热更新</h3><div id="policyConfig" class="config-list muted"><div v-for="(label, field) in configLabels" :key="field" class="config-row"><span>{{ label }}</span><input class="config-input" :data-field="field" v-model="overrides[field]" type="number" placeholder="默认"></div></div></section></div><h3>迁移分析</h3><div id="migrationAnalysis" class="compact-list muted"><div v-if="migration.center" class="row"><b>推荐中心</b> <span class="tag">{{ formatCell(migration.center) }}</span> <span class="tag">分数 {{ migration.score?.toFixed?.(1) || migration.score }}</span> <span :class="{ muted: !migrationFresh }">{{ migrationFresh ? '有效' : '已过期' }} ({{ Number(current?.tick || 0) - Number(migration.computed_at_tick || 0) }} Tick 前)</span></div><div v-if="migration.center" class="row"><small>扫描间隔 {{ migration.interval_ticks }} Tick · 上次 #{{ migration.computed_at_tick }}</small></div><div v-for="(candidate, index) in migration.candidates || []" :key="`${candidate.center}-${index}`" class="row"><span class="tick">#{{ Number(index) + 1 }}</span> <b>中心 {{ formatCell(candidate.center) }}</b> <span class="tag">分数 {{ candidate.score }}</span> <span class="muted">矿点 {{ candidate.resource_count }}</span></div><div v-if="!migration.center">尚无迁移分析数据</div></div><div class="button-row"><button id="triggerAnalysis" class="neutral" @click="dashboard.triggerAnalysis">立即扫描</button></div><p id="migrationState" class="muted">{{ dashboard.migrationState }}</p><h3>矿区饱和度</h3><div id="chunkSaturation" class="compact-list muted"><div v-for="(chunk, key) in chunks" :key="key" class="chunk-row"><span class="chunk-label">Chunk {{ key }}</span><span class="chunk-stats">{{ chunk.visible_count }}/{{ chunk.quota }}</span><div class="bar" style="height:5px"><i :style="{ width: `${Math.round((chunk.saturation || 0) * 100)}%`, background: (chunk.saturation || 0) >= .8 ? 'var(--cyan)' : (chunk.saturation || 0) >= .4 ? 'var(--amber)' : 'var(--red)' }"></i></div><small>补货倒计时 {{ chunk.refresh_countdown }} Tick</small></div><div v-if="!Object.keys(chunks).length">尚无已知矿区</div></div><h3>命令审计</h3><div id="commands" class="compact-list muted"><div v-for="item in commandCenter.commands || []" :key="`${item.command_id}-${item.status}`" class="row">{{ commandLabel(item.type) }} · {{ statusLabel(item.status) }}</div><div v-if="!commandCenter.commands?.length">尚无命令</div></div><h3>任务切换</h3><div id="timeline" class="compact-list muted"><div v-for="item in commandCenter.timeline || []" :key="`${item.tick}-${item.task_id}`" class="row"><span class="tick">#{{ item.tick }}</span> <b>{{ item.task_id }}</b> <span class="tag">{{ statusLabel(item.status) }}</span> {{ goalLabel(item.goal) || taskLabel(item.kind) }} {{ reasonLabel(item.reason) }}</div><div v-if="!commandCenter.timeline?.length">尚无任务切换记录</div></div></details>
  </aside>
</template>
